                else:
                    is_credit_val = False
                if is_credit_val != rule['is_credit']:
                    matches = False

            # Check aci
            if matches and rule['aci'] is not None and rule['aci'] != []:
                if txn['aci'] not in rule['aci']:
                    matches = False

            # Check merchant_category_code
            if matches and rule['merchant_category_code'] is not None and rule['merchant_category_code'] != []:
                if merchant_info['merchant_category_code'] not in rule['merchant_category_code']:
                    matches = False

            # Check intracountry
            if matches and rule['intracountry'] is not None:
                is_intracountry_val = (txn['issuing_country'] == txn['acquirer_country'])
                if is_intracountry_val != rule['intracountry']:
                    matches = False

            if matches:
                # Calculate fee for this rule
                fee = calculate_fee(rule['fixed_amount'], rule['rate'], float(txn['eur_amount']))
                total_fee += fee

    results.append({
        'card_scheme': scheme,
        'transaction_count': len(scheme_txns),
        'total_volume': scheme_txns['eur_amount'].astype(float).sum(),
        'total_fees': total_fee
    })

